149	
150	  private static final float MAX_AVG_VARIANCE = 0.25f;
151	  private static final float MAX_INDIVIDUAL_VARIANCE = 0.7f;
152	
153	  private static final int CODE_SHIFT = 98;
154	
155	  private static final int CODE_CODE_C = 99;
156	  private static final int CODE_CODE_B = 100;
157	  private static final int CODE_CODE_A = 101;
158	
159	  private static final int CODE_FNC_1 = 102;
160	  private static final int CODE_FNC_2 = 97;
161	  private static final int CODE_FNC_3 = 96;
162	  private static final int CODE_FNC_4_A = 101;
163	  private static final int CODE_FNC_4_B = 100;
164	
165	  private static final int CODE_START_A = 103;
166	  private static final int CODE_START_B = 104;
167	  private static final int CODE_START_C = 105;
168	  private static final int CODE_STOP = 106;
169	
170	  private static int[] findStartPattern(BitArray row) throws NotFoundException {
171	    int width = row.getSize();
172	    int rowOffset = row.getNextSet(0);
173	
174	    int counterPosition = 0;
175	    int[] counters = new int[6];
176	    int patternStart = rowOffset;
177	    boolean isWhite = false;
178	    int patternLength = counters.length;
179	
180	    for (int i = rowOffset; i < width; i++) {
181	      if (row.get(i) != isWhite) {
182	        counters[counterPosition]++;
183	      } else {
184	        if (counterPosition == patternLength - 1) {
185	          float bestVariance = MAX_AVG_VARIANCE;
186	          int bestMatch = -1;
187	          for (int startCode = CODE_START_A; startCode <= CODE_START_C; startCode++) {
188	            float variance = patternMatchVariance(counters, CODE_PATTERNS[startCode],
189	                MAX_INDIVIDUAL_VARIANCE);
190	            if (variance < bestVariance) {
191	              bestVariance = variance;
192	              bestMatch = startCode;
193	            }
194	          }
195	          // Look for whitespace before start pattern, >= 50% of width of start pattern
196	          if (bestMatch >= 0 &&
197	              row.isRange(Math.max(0, patternStart - (i - patternStart) / 2), patternStart, false)) {
198	            return new int[]{patternStart, i, bestMatch};
199	          }
200	          patternStart += counters[0] + counters[1];
201	          System.arraycopy(counters, 2, counters, 0, counterPosition - 1);
202	          counters[counterPosition - 1] = 0;
203	          counters[counterPosition] = 0;
204	          counterPosition--;
205	        } else {
206	          counterPosition++;
207	        }
208	        counters[counterPosition] = 1;
209	        isWhite = !isWhite;
210	      }
211	    }
212	    throw NotFoundException.getNotFoundInstance();
213	  }
214	
215	  private static int decodeCode(BitArray row, int[] counters, int rowOffset)
216	      throws NotFoundException {
217	    recordPattern(row, rowOffset, counters);
218	    float bestVariance = MAX_AVG_VARIANCE; // worst variance we'll accept
219	    int bestMatch = -1;
220	    for (int d = 0; d < CODE_PATTERNS.length; d++) {
221	      int[] pattern = CODE_PATTERNS[d];
222	      float variance = patternMatchVariance(counters, pattern, MAX_INDIVIDUAL_VARIANCE);
223	      if (variance < bestVariance) {
224	        bestVariance = variance;
225	        bestMatch = d;
226	      }
227	    }
228	    // TODO We're overlooking the fact that the STOP pattern has 7 values, not 6.
229	    if (bestMatch >= 0) {
230	      return bestMatch;
231	    } else {
232	      throw NotFoundException.getNotFoundInstance();
233	    }
234	  }
235	
236	  @Override
237	  public Result decodeRow(int rowNumber, BitArray row, Map<DecodeHintType,?> hints)
238	      throws NotFoundException, FormatException, ChecksumException {
239	
240	    boolean convertFNC1 = hints != null && hints.containsKey(DecodeHintType.ASSUME_GS1);
241	
242	    int symbologyModifier = 0;
243	    boolean readerInit = false;
244	
245	    int[] startPatternInfo = findStartPattern(row);
246	    int startCode = startPatternInfo[2];
247	
248	    List<Byte> rawCodes = new ArrayList<>(20);
249	    rawCodes.add((byte) startCode);
250	
251	    int codeSet;
252	    switch (startCode) {
253	      case CODE_START_A:
254	        codeSet = CODE_CODE_A;
255	        break;
256	      case CODE_START_B:
257	        codeSet = CODE_CODE_B;
258	        break;
259	      case CODE_START_C:
260	        codeSet = CODE_CODE_C;
261	        break;
262	      default:
263	        throw FormatException.getFormatInstance();
264	    }
265	
266	    boolean done = false;
267	    boolean isNextShifted = false;
268	
269	    StringBuilder result = new StringBuilder(20);
270	
271	    int lastStart = startPatternInfo[0];
272	    int nextStart = startPatternInfo[1];
273	    int[] counters = new int[6];
274	
275	    int lastCode = 0;
276	    int code = 0;
277	    int checksumTotal = startCode;
278	    int multiplier = 0;
279	    int lastResultLength = 0;
280	    int lastSymbologyModifier = symbologyModifier;
281	    boolean lastReaderInit = readerInit;
282	    boolean upperMode = false;
283	    boolean shiftUpperMode = false;
284	
285	    while (!done) {
286	
287	      boolean unshift = isNextShifted;
288	      isNextShifted = false;
289	
290	      // Save off last code
291	      lastCode = code;
292	
293	      // Decode another code from image
294	      code = decodeCode(row, counters, nextStart);
295	
296	      rawCodes.add((byte) code);
297	
298	      // Save the output in case this code is the checksum.
299	      if (code != CODE_STOP) {
300	        lastResultLength = result.length();
301	        lastSymbologyModifier = symbologyModifier;
302	        lastReaderInit = readerInit;
303	        multiplier++;
304	        checksumTotal += multiplier * code;
305	      }
306	
307	      // Advance to where the next code will to start
308	      lastStart = nextStart;
309	      for (int counter : counters) {
310	        nextStart += counter;
311	      }
312	
313	      // Take care of illegal start codes
314	      switch (code) {
315	        case CODE_START_A:
316	        case CODE_START_B:
317	        case CODE_START_C:
318	          throw FormatException.getFormatInstance();
319	      }
320	
321	      switch (codeSet) {
322	
323	        case CODE_CODE_A:
324	          if (code < 64) {
325	            if (shiftUpperMode == upperMode) {
326	              result.append((char) (' ' + code));
327	            } else {
328	              result.append((char) (' ' + code + 128));
329	            }
330	            shiftUpperMode = false;
331	          } else if (code < 96) {
332	            if (shiftUpperMode == upperMode) {
333	              result.append((char) (code - 64));
334	            } else {
335	              result.append((char) (code + 64));
336	            }
337	            shiftUpperMode = false;
338	          } else {
339	            switch (code) {
340	              case CODE_FNC_1:
341	                symbologyModifier = handleFNC1(result, convertFNC1, symbologyModifier);
342	                break;
343	              case CODE_FNC_2:
344	                symbologyModifier = 4;
345	                break;
346	              case CODE_FNC_3:
347	                readerInit = true;
348	                break;
349	              case CODE_FNC_4_A:
350	                if (!upperMode && shiftUpperMode) {
351	                  upperMode = true;
352	                  shiftUpperMode = false;
353	                } else if (upperMode && shiftUpperMode) {
354	                  upperMode = false;
355	                  shiftUpperMode = false;
356	                } else {
357	                  shiftUpperMode = true;
358	                }
359	                break;
360	              case CODE_SHIFT:
361	                isNextShifted = true;
362	                codeSet = CODE_CODE_B;
363	                break;
364	              case CODE_CODE_B:
365	                codeSet = CODE_CODE_B;
366	                break;
367	              case CODE_CODE_C:
368	                codeSet = CODE_CODE_C;
369	                break;
370	              case CODE_STOP:
371	                done = true;
372	                break;
373	            }
374	          }
375	          break;
376	        case CODE_CODE_B:
377	          if (code < 96) {
378	            if (shiftUpperMode == upperMode) {
379	              result.append((char) (' ' + code));
380	            } else {
381	              result.append((char) (' ' + code + 128));
382	            }
383	            shiftUpperMode = false;
384	          } else {
385	            switch (code) {
386	              case CODE_FNC_1:
387	                symbologyModifier = handleFNC1(result, convertFNC1, symbologyModifier);
388	                break;
389	              case CODE_FNC_2:
390	                symbologyModifier = 4;
391	                break;
392	              case CODE_FNC_3:
393	                readerInit = true;
394	                break;
395	              case CODE_FNC_4_B:
396	                if (!upperMode && shiftUpperMode) {
397	                  upperMode = true;
398	                  shiftUpperMode = false;
399	                } else if (upperMode && shiftUpperMode) {
400	                  upperMode = false;
401	                  shiftUpperMode = false;
402	                } else {
403	                  shiftUpperMode = true;
404	                }
405	                break;
406	              case CODE_SHIFT:
407	                isNextShifted = true;
408	                codeSet = CODE_CODE_A;
409	                break;
410	              case CODE_CODE_A:
411	                codeSet = CODE_CODE_A;
412	                break;
413	              case CODE_CODE_C:
414	                codeSet = CODE_CODE_C;
415	                break;
416	              case CODE_STOP:
417	                done = true;
418	                break;
419	            }
420	          }
421	          break;
422	        case CODE_CODE_C:
423	          if (code < 100) {
424	            if (code < 10) {
425	              result.append('0');
426	            }
427	            result.append(code);
428	          } else {
429	            switch (code) {
430	              case CODE_FNC_1:
431	                symbologyModifier = handleFNC1(result, convertFNC1, symbologyModifier);
432	                break;
433	              case CODE_CODE_A:
434	                codeSet = CODE_CODE_A;
435	                break;
436	              case CODE_CODE_B:
437	                codeSet = CODE_CODE_B;
438	                break;
439	              case CODE_STOP:
440	                done = true;
441	                break;
442	            }
443	          }
444	          break;
445	      }
446	
447	      // Unshift back to another code set if we were shifted
448	      if (unshift) {
449	        codeSet = codeSet == CODE_CODE_A ? CODE_CODE_B : CODE_CODE_A;
450	      }
451	
452	    }
453	
454	    int lastPatternSize = nextStart - lastStart;
455	
456	    // Check for ample whitespace following pattern, but, to do this we first need to remember that
457	    // we fudged decoding CODE_STOP since it actually has 7 bars, not 6. There is a black bar left
458	    // to read off. Would be slightly better to properly read. Here we just skip it:
459	    nextStart = row.getNextUnset(nextStart);
460	    if (!row.isRange(nextStart,
461	                     Math.min(row.getSize(), nextStart + (nextStart - lastStart) / 2),
462	                     false)) {
463	      throw NotFoundException.getNotFoundInstance();
464	    }
465	
466	    // Pull out from sum the value of the penultimate check code
467	    checksumTotal -= multiplier * lastCode;
468	    // lastCode is the checksum then:
469	    if (checksumTotal % 103 != lastCode) {
470	      throw ChecksumException.getChecksumInstance();
471	    }
472	
473	    int resultLength = result.length();
474	    if (resultLength == 0) {
475	      // false positive
476	      throw NotFoundException.getNotFoundInstance();
477	    }
478	
479	    // Discard the checksum's text and function code effects.
480	    result.setLength(lastResultLength);
481	    symbologyModifier = lastSymbologyModifier;
482	    readerInit = lastReaderInit;
483	
484	    float left = (startPatternInfo[1] + startPatternInfo[0]) / 2.0f;
485	    float right = lastStart + lastPatternSize / 2.0f;
486	
487	    int rawCodesSize = rawCodes.size();
488	    byte[] rawBytes = new byte[rawCodesSize];
489	    for (int i = 0; i < rawCodesSize; i++) {
490	      rawBytes[i] = rawCodes.get(i);
491	    }
492	
493	    Result resultObject = new Result(
494	        result.toString(),
495	        rawBytes,
496	        new ResultPoint[]{
497	            new ResultPoint(left, rowNumber),
498	            new ResultPoint(right, rowNumber)},
499	        BarcodeFormat.CODE_128);
500	
501	    resultObject.putMetadata(ResultMetadataType.SYMBOLOGY_IDENTIFIER, "]C" + symbologyModifier);
502	    resultObject.putMetadata(ResultMetadataType.READER_INIT, readerInit);
503	
504	    return resultObject;
505	  }
506	
507	  private static int handleFNC1(StringBuilder result, boolean convertFNC1, int symbologyModifier) {
508	    int len = result.length();
509	    if (len == 0) {
510	      symbologyModifier = 1;
511	    } else if (len == 1) {
512	      symbologyModifier = 2;
513	    }
514	    if (convertFNC1) {
515	      if (len == 0) {
516	        result.append("]C1");
517	      } else {
518	        result.append((char) 29);
519	      }
520	    }
521	    return symbologyModifier;
522	  }
523	
524	}
