17	package com.google.zxing.oned;
18	
19	import com.google.zxing.BarcodeFormat;
20	import com.google.zxing.DecodeHintType;
21	import com.google.zxing.NotFoundException;
22	import com.google.zxing.Reader;
23	import com.google.zxing.ReaderException;
24	import com.google.zxing.Result;
25	import com.google.zxing.common.BitArray;
26	import com.google.zxing.oned.rss.RSS14Reader;
27	import com.google.zxing.oned.rss.expanded.RSSExpandedReader;
28	
29	import java.util.ArrayList;
30	import java.util.Collection;
31	import java.util.Map;
32	
33	/**
34	 * @author dswitkin@google.com (Daniel Switkin)
35	 * @author Sean Owen
36	 */
37	public final class MultiFormatOneDReader extends OneDReader {
38	
39	  private static final OneDReader[] EMPTY_ONED_ARRAY = new OneDReader[0];
40	
41	  private final OneDReader[] readers;
42	
43	  public MultiFormatOneDReader(Map<DecodeHintType,?> hints) {
44	    @SuppressWarnings("unchecked")
45	    Collection<BarcodeFormat> possibleFormats = hints == null ? null :
46	        (Collection<BarcodeFormat>) hints.get(DecodeHintType.POSSIBLE_FORMATS);
47	    boolean useCode39CheckDigit = hints != null &&
48	        hints.get(DecodeHintType.ASSUME_CODE_39_CHECK_DIGIT) != null;
49	    Collection<OneDReader> readers = new ArrayList<>();
50	    if (possibleFormats != null) {
51	      if (possibleFormats.contains(BarcodeFormat.EAN_13) ||
52	          possibleFormats.contains(BarcodeFormat.UPC_A) ||
53	          possibleFormats.contains(BarcodeFormat.EAN_8) ||
54	          possibleFormats.contains(BarcodeFormat.UPC_E)) {
55	        readers.add(new MultiFormatUPCEANReader(hints));
56	      }
57	      if (possibleFormats.contains(BarcodeFormat.CODE_39)) {
58	        readers.add(new Code39Reader(useCode39CheckDigit));
59	      }
60	      if (possibleFormats.contains(BarcodeFormat.CODE_93)) {
61	        readers.add(new Code93Reader());
62	      }
63	      if (possibleFormats.contains(BarcodeFormat.CODE_128)) {
64	        readers.add(new Code128Reader());
65	      }
66	      if (possibleFormats.contains(BarcodeFormat.ITF)) {
67	        readers.add(new ITFReader());
68	      }
69	      if (possibleFormats.contains(BarcodeFormat.CODABAR)) {
70	        readers.add(new CodaBarReader());
71	      }
72	      if (possibleFormats.contains(BarcodeFormat.RSS_14)) {
73	        readers.add(new RSS14Reader());
74	      }
75	      if (possibleFormats.contains(BarcodeFormat.RSS_EXPANDED)) {
76	        readers.add(new RSSExpandedReader());
77	      }
78	    }
79	    if (readers.isEmpty()) {
80	      readers.add(new MultiFormatUPCEANReader(hints));
81	      readers.add(new Code39Reader());
82	      readers.add(new CodaBarReader());
83	      readers.add(new Code93Reader());
84	      readers.add(new Code128Reader());
85	      readers.add(new ITFReader());
86	      readers.add(new RSS14Reader());
87	      readers.add(new RSSExpandedReader());
88	    }
89	    this.readers = readers.toArray(EMPTY_ONED_ARRAY);
90	  }
