30	/**
31	 * Encapsulates logic that can detect an Aztec Code in an image, even if the Aztec Code
32	 * is rotated or skewed, or partially obscured.
33	 *
34	 * @author David Olivier
35	 * @author Frank Yellin
36	 */
37	public final class Detector {
38	
39	  private static final int[] EXPECTED_CORNER_BITS = {
40	      0xee0,  // 07340  XXX .XX X.. ...
41	      0x1dc,  // 00734  ... XXX .XX X..
42	      0x83b,  // 04073  X.. ... XXX .XX
43	      0x707,  // 03407 .XX X.. ... XXX
44	  };
45	
46	  private final BitMatrix image;
47	
48	  private boolean compact;
49	  private boolean readerInit;
50	  private int nbLayers;
51	  private int nbDataBlocks;
52	  private int nbCenterLayers;
53	  private int shift;
54	
55	  public Detector(BitMatrix image) {
56	    this.image = image;
57	  }
58	
59	  public AztecDetectorResult detect() throws NotFoundException {
60	    return detect(false);
61	  }
62	
63	  /**
64	   * Detects an Aztec Code in an image.
65	   *
66	   * @param isMirror if true, image is a mirror-image of original
67	   * @return {@link AztecDetectorResult} encapsulating results of detecting an Aztec Code
68	   * @throws NotFoundException if no Aztec Code can be found
69	   */
70	  public AztecDetectorResult detect(boolean isMirror) throws NotFoundException {
71	
72	    // 1. Get the center of the aztec matrix
73	    Point pCenter = getMatrixCenter();
74	
75	    // 2. Get the center points of the four diagonal points just outside the bull's eye
76	    //  [topRight, bottomRight, bottomLeft, topLeft]
77	    ResultPoint[] bullsEyeCorners = getBullsEyeCorners(pCenter);
78	
79	    if (isMirror) {
80	      ResultPoint temp = bullsEyeCorners[0];
81	      bullsEyeCorners[0] = bullsEyeCorners[2];
82	      bullsEyeCorners[2] = temp;
83	    }
84	
85	    // 3. Get the size of the matrix and other parameters from the bull's eye
86	    int errorsCorrected = extractParameters(bullsEyeCorners);
87	
88	    // 4. Sample the grid
89	    BitMatrix bits = sampleGrid(image,
90	                                bullsEyeCorners[shift % 4],
91	                                bullsEyeCorners[(shift + 1) % 4],
92	                                bullsEyeCorners[(shift + 2) % 4],
93	                                bullsEyeCorners[(shift + 3) % 4]);
94	
95	    // 5. Get the corners of the matrix.
96	    ResultPoint[] corners = getMatrixCornerPoints(bullsEyeCorners);
97	
98	    return new AztecDetectorResult(bits, corners, compact, nbDataBlocks, nbLayers, errorsCorrected, readerInit);
99	  }
100	
101	  /**
102	   * Extracts the number of data layers and data blocks from the layer around the bull's eye.
103	   *
104	   * @param bullsEyeCorners the array of bull's eye corners
105	   * @return the number of errors corrected during parameter extraction
106	   * @throws NotFoundException in case of too many errors or invalid parameters
107	   */
108	  private int extractParameters(ResultPoint[] bullsEyeCorners) throws NotFoundException {
109	    if (!isValid(bullsEyeCorners[0]) || !isValid(bullsEyeCorners[1]) ||
110	        !isValid(bullsEyeCorners[2]) || !isValid(bullsEyeCorners[3])) {
111	      throw NotFoundException.getNotFoundInstance();
112	    }
113	    int length = 2 * nbCenterLayers;
114	    // Get the bits around the bull's eye
115	    int[] sides = {
116	        sampleLine(bullsEyeCorners[0], bullsEyeCorners[1], length), // Right side
117	        sampleLine(bullsEyeCorners[1], bullsEyeCorners[2], length), // Bottom
118	        sampleLine(bullsEyeCorners[2], bullsEyeCorners[3], length), // Left side
119	        sampleLine(bullsEyeCorners[3], bullsEyeCorners[0], length)  // Top
120	    };
121	
122	    // bullsEyeCorners[shift] is the corner of the bulls'eye that has three
123	    // orientation marks.
124	    // sides[shift] is the row/column that goes from the corner with three
125	    // orientation marks to the corner with two.
126	    shift = getRotation(sides, length);
127	
128	    // Flatten the parameter bits into a single 28- or 40-bit long
129	    long parameterData = 0;
130	    for (int i = 0; i < 4; i++) {
131	      int side = sides[(shift + i) % 4];
132	      if (compact) {
133	        // Each side of the form ..XXXXXXX. where Xs are parameter data
134	        parameterData <<= 7;
135	        parameterData += (side >> 1) & 0x7F;
136	      } else {
137	        // Each side of the form ..XXXXX.XXXXX. where Xs are parameter data
138	        parameterData <<= 10;
139	        parameterData += ((side >> 2) & (0x1f << 5)) + ((side >> 1) & 0x1F);
140	      }
141	    }
142	
143	    // Corrects parameter data using RS.  Returns just the data portion
144	    // without the error correction.
145	    CorrectedParameter correctedParam = getCorrectedParameterData(parameterData, compact);
146	    int correctedData = correctedParam.getData();
147	
148	    int dataMsb;
149	    if (compact) {
150	      // 8 bits:  2 bits layers and 6 bits data blocks
151	      nbLayers = (correctedData >> 6) + 1;
152	      nbDataBlocks = (correctedData & 0x3F) + 1;
153	      dataMsb = (correctedData & 0x3F) >> 5;
154	    } else {
155	      // 16 bits:  5 bits layers and 11 bits data blocks
156	      nbLayers = (correctedData >> 11) + 1;
157	      nbDataBlocks = (correctedData & 0x7FF) + 1;
158	      dataMsb = (correctedData & 0x7FF) >> 10;
159	    }
160	
161	    // If the most significant bit of D is set and D exceeds the capacity of L data layers,
162	    // this symbols is identified as a reader initialization symbol and the most significant
163	    // bit of D is cleared.
164	    if (dataMsb == 1) {
165	      int codewordSize;
166	      if (nbLayers <= 2) {
167	        codewordSize = 6;
168	      } else if (nbLayers <= 8) {
169	        codewordSize = 8;
170	      } else if (nbLayers <= 22) {
171	        codewordSize = 10;
172	      } else {
173	        codewordSize = 12;
174	      }
175	      int layersBitCapacity = ((compact ? 88 : 112) + 16 * nbLayers) * nbLayers;
176	      int dataBits = nbDataBlocks * codewordSize;
177	      if (dataBits > layersBitCapacity) {
178	        int mask = (compact ? 0x1F : 0x3FF);
179	        nbDataBlocks = ((nbDataBlocks - 1) & mask) + 1; // clear data MSB
180	        readerInit = true;
181	      }
182	    }
183	
184	    return correctedParam.getErrorsCorrected();
185	  }
186	
187	  private static int getRotation(int[] sides, int length) throws NotFoundException {
188	    // In a normal pattern, we expect to See
189	    //   **    .*             D       A
190	    //   *      *
191	    //
192	    //   .      *
193	    //   ..    ..             C       B
194	    //
195	    // Grab the 3 bits from each of the sides the form the locator pattern and concatenate
196	    // into a 12-bit integer.  Start with the bit at A
197	    int cornerBits = 0;
198	    for (int side : sides) {
199	      // XX......X where X's are orientation marks
200	      int t = ((side >> (length - 2)) << 1) + (side & 1);
201	      cornerBits = (cornerBits << 3) + t;
202	    }
203	    // Mov the bottom bit to the top, so that the three bits of the locator pattern at A are
204	    // together.  cornerBits is now:
205	    //  3 orientation bits at A || 3 orientation bits at B || ... || 3 orientation bits at D
206	    cornerBits = ((cornerBits & 1) << 11) + (cornerBits >> 1);
207	    // The result shift indicates which element of BullsEyeCorners[] goes into the top-left
208	    // corner. Since the four rotation values have a Hamming distance of 8, we
209	    // can easily tolerate two errors.
210	    for (int shift = 0; shift < 4; shift++) {
211	      if (Integer.bitCount(cornerBits ^ EXPECTED_CORNER_BITS[shift]) <= 2) {
212	        return shift;
213	      }
214	    }
215	    throw NotFoundException.getNotFoundInstance();
216	  }
217	
218	  /**
219	   * Corrects the parameter bits using Reed-Solomon algorithm.
220	   *
221	   * @param parameterData parameter bits
222	   * @param compact true if this is a compact Aztec code
223	   * @return the corrected parameter
224	   * @throws NotFoundException if the array contains too many errors
225	   */
226	  private static CorrectedParameter getCorrectedParameterData(long parameterData,
227	                                                              boolean compact) throws NotFoundException {
228	    int numCodewords;
229	    int numDataCodewords;
230	
231	    if (compact) {
232	      numCodewords = 7;
233	      numDataCodewords = 2;
234	    } else {
235	      numCodewords = 10;
236	      numDataCodewords = 4;
237	    }
238	
239	    int numECCodewords = numCodewords - numDataCodewords;
240	    int[] parameterWords = new int[numCodewords];
241	    for (int i = numCodewords - 1; i >= 0; --i) {
242	      parameterWords[i] = (int) parameterData & 0xF;
243	      parameterData >>= 4;
244	    }
245	
246	    int errorsCorrected = 0;
247	    try {
248	      ReedSolomonDecoder rsDecoder = new ReedSolomonDecoder(GenericGF.AZTEC_PARAM);
249	      errorsCorrected = rsDecoder.decodeWithECCount(parameterWords, numECCodewords);
250	    } catch (ReedSolomonException ignored) {
251	      throw NotFoundException.getNotFoundInstance();
252	    }
253	
254	    // Toss the error correction.  Just return the data as an integer
255	    int result = 0;
256	    for (int i = 0; i < numDataCodewords; i++) {
257	      result = (result << 4) + parameterWords[i];
258	    }
259	    return new CorrectedParameter(result, errorsCorrected);
260	  }
261	
262	  /**
263	   * Finds the corners of a bull-eye centered on the passed point.
264	   * This returns the centers of the diagonal points just outside the bull's eye
265	   * Returns [topRight, bottomRight, bottomLeft, topLeft]
266	   *
267	   * @param pCenter Center point
268	   * @return The corners of the bull-eye
269	   * @throws NotFoundException If no valid bull-eye can be found
270	   */
271	  private ResultPoint[] getBullsEyeCorners(Point pCenter) throws NotFoundException {
272	
273	    Point pina = pCenter;
274	    Point pinb = pCenter;
275	    Point pinc = pCenter;
276	    Point pind = pCenter;
277	
278	    boolean color = true;
279	
280	    for (nbCenterLayers = 1; nbCenterLayers < 9; nbCenterLayers++) {
281	      Point pouta = getFirstDifferent(pina, color, 1, -1);
282	      Point poutb = getFirstDifferent(pinb, color, 1, 1);
283	      Point poutc = getFirstDifferent(pinc, color, -1, 1);
284	      Point poutd = getFirstDifferent(pind, color, -1, -1);
285	
286	      //d      a
287	      //
288	      //c      b
289	
290	      if (nbCenterLayers > 2) {
291	        float q = distance(poutd, pouta) * nbCenterLayers / (distance(pind, pina) * (nbCenterLayers + 2));
292	        if (q < 0.75 || q > 1.25 || !isWhiteOrBlackRectangle(pouta, poutb, poutc, poutd)) {
293	          break;
294	        }
295	      }
296	
297	      pina = pouta;
298	      pinb = poutb;
299	      pinc = poutc;
300	      pind = poutd;
301	
302	      color = !color;
303	    }
304	
305	    if (nbCenterLayers != 5 && nbCenterLayers != 7) {
306	      throw NotFoundException.getNotFoundInstance();
307	    }
308	
309	    compact = nbCenterLayers == 5;
310	
311	    // Expand the square by .5 pixel in each direction so that we're on the border
312	    // between the white square and the black square
313	    ResultPoint pinax = new ResultPoint(pina.getX() + 0.5f, pina.getY() - 0.5f);
314	    ResultPoint pinbx = new ResultPoint(pinb.getX() + 0.5f, pinb.getY() + 0.5f);
315	    ResultPoint pincx = new ResultPoint(pinc.getX() - 0.5f, pinc.getY() + 0.5f);
316	    ResultPoint pindx = new ResultPoint(pind.getX() - 0.5f, pind.getY() - 0.5f);
317	
318	    // Expand the square so that its corners are the centers of the points
319	    // just outside the bull's eye.
320	    return expandSquare(new ResultPoint[]{pinax, pinbx, pincx, pindx},
321	                        2 * nbCenterLayers - 3,
322	                        2 * nbCenterLayers);
323	  }
324	
325	  /**
326	   * Finds a candidate center point of an Aztec code from an image
327	   *
328	   * @return the center point
329	   */
330	  private Point getMatrixCenter() {
331	
332	    ResultPoint pointA;
333	    ResultPoint pointB;
334	    ResultPoint pointC;
335	    ResultPoint pointD;
336	
337	    //Get a white rectangle that can be the border of the matrix in center bull's eye or
338	    try {
339	
340	      ResultPoint[] cornerPoints = new WhiteRectangleDetector(image).detect();
341	      pointA = cornerPoints[0];
342	      pointB = cornerPoints[1];
343	      pointC = cornerPoints[2];
344	      pointD = cornerPoints[3];
345	
346	    } catch (NotFoundException e) {
347	
348	      // This exception can be in case the initial rectangle is white
349	      // In that case, surely in the bull's eye, we try to expand the rectangle.
350	      int cx = image.getWidth() / 2;
351	      int cy = image.getHeight() / 2;
352	      pointA = getFirstDifferent(new Point(cx + 7, cy - 7), false, 1, -1).toResultPoint();
353	      pointB = getFirstDifferent(new Point(cx + 7, cy + 7), false, 1, 1).toResultPoint();
354	      pointC = getFirstDifferent(new Point(cx - 7, cy + 7), false, -1, 1).toResultPoint();
355	      pointD = getFirstDifferent(new Point(cx - 7, cy - 7), false, -1, -1).toResultPoint();
356	
357	    }
358	
359	    //Compute the center of the rectangle
360	    int cx = MathUtils.round((pointA.getX() + pointD.getX() + pointB.getX() + pointC.getX()) / 4.0f);
361	    int cy = MathUtils.round((pointA.getY() + pointD.getY() + pointB.getY() + pointC.getY()) / 4.0f);
362	
363	    // Redetermine the white rectangle starting from previously computed center.
364	    // This will ensure that we end up with a white rectangle in center bull's eye
365	    // in order to compute a more accurate center.
366	    try {
367	      ResultPoint[] cornerPoints = new WhiteRectangleDetector(image, 15, cx, cy).detect();
368	      pointA = cornerPoints[0];
369	      pointB = cornerPoints[1];
370	      pointC = cornerPoints[2];
371	      pointD = cornerPoints[3];
372	    } catch (NotFoundException e) {
373	      // This exception can be in case the initial rectangle is white
374	      // In that case we try to expand the rectangle.
375	      pointA = getFirstDifferent(new Point(cx + 7, cy - 7), false, 1, -1).toResultPoint();
376	      pointB = getFirstDifferent(new Point(cx + 7, cy + 7), false, 1, 1).toResultPoint();
377	      pointC = getFirstDifferent(new Point(cx - 7, cy + 7), false, -1, 1).toResultPoint();
378	      pointD = getFirstDifferent(new Point(cx - 7, cy - 7), false, -1, -1).toResultPoint();
379	    }
380	
381	    // Recompute the center of the rectangle
382	    cx = MathUtils.round((pointA.getX() + pointD.getX() + pointB.getX() + pointC.getX()) / 4.0f);
383	    cy = MathUtils.round((pointA.getY() + pointD.getY() + pointB.getY() + pointC.getY()) / 4.0f);
384	
385	    return new Point(cx, cy);
386	  }
