388	  /**
389	   * Gets the Aztec code corners from the bull's eye corners and the parameters.
390	   *
391	   * @param bullsEyeCorners the array of bull's eye corners
392	   * @return the array of aztec code corners
393	   */
394	  private ResultPoint[] getMatrixCornerPoints(ResultPoint[] bullsEyeCorners) {
395	    return expandSquare(bullsEyeCorners, 2 * nbCenterLayers, getDimension());
396	  }
