398	  /**
399	   * Creates a BitMatrix by sampling the provided image.
400	   * topLeft, topRight, bottomRight, and bottomLeft are the centers of the squares on the
401	   * diagonal just outside the bull's eye.
402	   */
403	  private BitMatrix sampleGrid(BitMatrix image,
404	                               ResultPoint topLeft,
405	                               ResultPoint topRight,
406	                               ResultPoint bottomRight,
407	                               ResultPoint bottomLeft) throws NotFoundException {
408	
409	    GridSampler sampler = GridSampler.getInstance();
410	    int dimension = getDimension();
411	
412	    float low = dimension / 2.0f - nbCenterLayers;
413	    float high = dimension / 2.0f + nbCenterLayers;
414	
415	    return sampler.sampleGrid(image,
416	                              dimension,
417	                              dimension,
418	                              low, low,   // topleft
419	                              high, low,  // topright
420	                              high, high, // bottomright
421	                              low, high,  // bottomleft
422	                              topLeft.getX(), topLeft.getY(),
423	                              topRight.getX(), topRight.getY(),
424	                              bottomRight.getX(), bottomRight.getY(),
425	                              bottomLeft.getX(), bottomLeft.getY());
426	  }
427	
428	  /**
429	   * Samples a line.
430	   *
431	   * @param p1   start point (inclusive)
432	   * @param p2   end point (exclusive)
433	   * @param size number of bits
434	   * @return the array of bits as an int (first bit is high-order bit of result)
435	   */
436	  private int sampleLine(ResultPoint p1, ResultPoint p2, int size) {
437	    int result = 0;
438	
439	    float d = distance(p1, p2);
440	    float moduleSize = d / size;
441	    float px = p1.getX();
442	    float py = p1.getY();
443	    float dx = moduleSize * (p2.getX() - p1.getX()) / d;
444	    float dy = moduleSize * (p2.getY() - p1.getY()) / d;
445	    for (int i = 0; i < size; i++) {
446	      if (image.get(MathUtils.round(px + i * dx), MathUtils.round(py + i * dy))) {
447	        result |= 1 << (size - i - 1);
448	      }
449	    }
450	    return result;
451	  }
452	
453	  /**
454	   * @return true if the border of the rectangle passed in parameter is compound of white points only
455	   *         or black points only
456	   */
457	  private boolean isWhiteOrBlackRectangle(Point p1,
458	                                          Point p2,
459	                                          Point p3,
460	                                          Point p4) {
461	
462	    int corr = 3;
463	
464	    p1 = new Point(Math.max(0, p1.getX() - corr), Math.min(image.getHeight() - 1, p1.getY() + corr));
465	    p2 = new Point(Math.max(0, p2.getX() - corr), Math.max(0, p2.getY() - corr));
466	    p3 = new Point(Math.min(image.getWidth() - 1, p3.getX() + corr),
467	                   Math.max(0, Math.min(image.getHeight() - 1, p3.getY() - corr)));
468	    p4 = new Point(Math.min(image.getWidth() - 1, p4.getX() + corr),
469	                   Math.min(image.getHeight() - 1, p4.getY() + corr));
470	
471	    int cInit = getColor(p4, p1);
472	
473	    if (cInit == 0) {
474	      return false;
475	    }
476	
477	    int c = getColor(p1, p2);
478	
479	    if (c != cInit) {
480	      return false;
481	    }
482	
483	    c = getColor(p2, p3);
484	
485	    if (c != cInit) {
486	      return false;
487	    }
488	
489	    c = getColor(p3, p4);
490	
491	    return c == cInit;
492	
493	  }
494	
495	  /**
496	   * Gets the color of a segment
497	   *
498	   * @return 1 if segment more than 90% black, -1 if segment is more than 90% white, 0 else
499	   */
500	  private int getColor(Point p1, Point p2) {
501	    float d = distance(p1, p2);
502	    if (d == 0.0f) {
503	      return 0;
504	    }
505	    float dx = (p2.getX() - p1.getX()) / d;
506	    float dy = (p2.getY() - p1.getY()) / d;
507	    int error = 0;
508	
509	    float px = p1.getX();
510	    float py = p1.getY();
511	
512	    boolean colorModel = image.get(p1.getX(), p1.getY());
513	
514	    int iMax = (int) Math.floor(d);
515	    for (int i = 0; i < iMax; i++) {
516	      if (image.get(MathUtils.round(px), MathUtils.round(py)) != colorModel) {
517	        error++;
518	      }
519	      px += dx;
520	      py += dy;
521	    }
522	
523	    float errRatio = error / d;
524	
525	    if (errRatio > 0.1f && errRatio < 0.9f) {
526	      return 0;
527	    }
528	
529	    return (errRatio <= 0.1f) == colorModel ? 1 : -1;
530	  }
531	
532	  /**
533	   * Gets the coordinate of the first point with a different color in the given direction
534	   */
535	  private Point getFirstDifferent(Point init, boolean color, int dx, int dy) {
536	    int x = init.getX() + dx;
537	    int y = init.getY() + dy;
538	
539	    while (isValid(x, y) && image.get(x, y) == color) {
540	      x += dx;
541	      y += dy;
542	    }
543	
544	    x -= dx;
545	    y -= dy;
546	
547	    while (isValid(x, y) && image.get(x, y) == color) {
548	      x += dx;
549	    }
550	    x -= dx;
551	
552	    while (isValid(x, y) && image.get(x, y) == color) {
553	      y += dy;
554	    }
555	    y -= dy;
556	
557	    return new Point(x, y);
558	  }
