560	  /**
561	   * Expand the square represented by the corner points by pushing out equally in all directions
562	   *
563	   * @param cornerPoints the corners of the square, which has the bull's eye at its center
564	   * @param oldSide the original length of the side of the square in the target bit matrix
565	   * @param newSide the new length of the size of the square in the target bit matrix
566	   * @return the corners of the expanded square
567	   */
568	  private static ResultPoint[] expandSquare(ResultPoint[] cornerPoints, int oldSide, int newSide) {
569	    float ratio = newSide / (2.0f * oldSide);
570	    float dx = cornerPoints[0].getX() - cornerPoints[2].getX();
571	    float dy = cornerPoints[0].getY() - cornerPoints[2].getY();
572	    float centerx = (cornerPoints[0].getX() + cornerPoints[2].getX()) / 2.0f;
573	    float centery = (cornerPoints[0].getY() + cornerPoints[2].getY()) / 2.0f;
574	
575	    ResultPoint result0 = new ResultPoint(centerx + ratio * dx, centery + ratio * dy);
576	    ResultPoint result2 = new ResultPoint(centerx - ratio * dx, centery - ratio * dy);
577	
578	    dx = cornerPoints[1].getX() - cornerPoints[3].getX();
579	    dy = cornerPoints[1].getY() - cornerPoints[3].getY();
580	    centerx = (cornerPoints[1].getX() + cornerPoints[3].getX()) / 2.0f;
581	    centery = (cornerPoints[1].getY() + cornerPoints[3].getY()) / 2.0f;
582	    ResultPoint result1 = new ResultPoint(centerx + ratio * dx, centery + ratio * dy);
583	    ResultPoint result3 = new ResultPoint(centerx - ratio * dx, centery - ratio * dy);
584	
585	    return new ResultPoint[]{result0, result1, result2, result3};
586	  }
587	
588	  private boolean isValid(int x, int y) {
589	    return x >= 0 && x < image.getWidth() && y >= 0 && y < image.getHeight();
590	  }
591	
592	  private boolean isValid(ResultPoint point) {
593	    int x = MathUtils.round(point.getX());
594	    int y = MathUtils.round(point.getY());
595	    return isValid(x, y);
596	  }
597	
598	  private static float distance(Point a, Point b) {
599	    return MathUtils.distance(a.getX(), a.getY(), b.getX(), b.getY());
600	  }
601	
602	  private static float distance(ResultPoint a, ResultPoint b) {
603	    return MathUtils.distance(a.getX(), a.getY(), b.getX(), b.getY());
604	  }
605	
606	  private int getDimension() {
607	    if (compact) {
608	      return 4 * nbLayers + 11;
609	    }
610	    return 4 * nbLayers + 2 * ((2 * nbLayers + 6) / 15) + 15;
611	  }
