26	/**
27	 * <p>MaxiCodes can encode text or structured information as bits in one of several modes,
28	 * with multiple character sets in one code. This class decodes the bits back into text.</p>
29	 *
30	 * @author mike32767
31	 * @author Manuel Kasten
32	 */
33	final class DecodedBitStreamParser {
34	
35	  private static final char SHIFTA = '\uFFF0';
36	  private static final char SHIFTB = '\uFFF1';
37	  private static final char SHIFTC = '\uFFF2';
38	  private static final char SHIFTD = '\uFFF3';
39	  private static final char SHIFTE = '\uFFF4';
40	  private static final char TWOSHIFTA = '\uFFF5';
41	  private static final char THREESHIFTA = '\uFFF6';
42	  private static final char LATCHA = '\uFFF7';
43	  private static final char LATCHB = '\uFFF8';
44	  private static final char LOCK = '\uFFF9';
45	  private static final char ECI = '\uFFFA';
46	  private static final char NS = '\uFFFB';
47	  private static final char PAD = '\uFFFC';
48	  private static final char FS = '\u001C';
49	  private static final char GS = '\u001D';
50	  private static final char RS = '\u001E';
51	  private static final byte[] COUNTRY_BYTES = { 53, 54, 43, 44, 45, 46, 47, 48, 37, 38 };
52	  private static final byte[] SERVICE_CLASS_BYTES = { 55, 56, 57, 58, 59, 60, 49, 50, 51, 52 };
53	  private static final byte[] POSTCODE_2_LENGTH_BYTES = { 39, 40, 41, 42, 31, 32 };
54	  private static final byte[] POSTCODE_2_BYTES = { 33, 34, 35, 36, 25, 26, 27, 28, 29, 30, 19,
55	      20, 21, 22, 23, 24, 13, 14, 15, 16, 17, 18, 7, 8, 9, 10, 11, 12, 1, 2 };
56	  private static final byte[][] POSTCODE_3_BYTES = {
57	      { 39, 40, 41, 42, 31, 32},
58	      { 33, 34, 35, 36, 25, 26},
59	      { 27, 28, 29, 30, 19, 20},
60	      { 21, 22, 23, 24, 13, 14},
61	      { 15, 16, 17, 18,  7,  8},
62	      {  9, 10, 11, 12,  1,  2}
63	  };
64	
65	  @SuppressWarnings("checkstyle:lineLength")
66	  private static final String[] SETS = {
67	    "\rABCDEFGHIJKLMNOPQRSTUVWXYZ" + ECI + FS + GS + RS + NS + ' ' + PAD +
68	        "\"#$%&'()*+,-./0123456789:" + SHIFTB + SHIFTC + SHIFTD + SHIFTE + LATCHB,
69	    "`abcdefghijklmnopqrstuvwxyz" + ECI + FS + GS + RS + NS + '{' + PAD +
70	        "}~\u007F;<=>?[\\]^_ ,./:@!|" + PAD + TWOSHIFTA + THREESHIFTA + PAD +
71	        SHIFTA + SHIFTC + SHIFTD + SHIFTE + LATCHA,
72	    "\u00C0\u00C1\u00C2\u00C3\u00C4\u00C5\u00C6\u00C7\u00C8\u00C9\u00CA\u00CB\u00CC\u00CD\u00CE\u00CF\u00D0\u00D1\u00D2\u00D3\u00D4\u00D5\u00D6\u00D7\u00D8\u00D9\u00DA" +
73	        ECI + FS + GS + RS + NS +
74	        "\u00DB\u00DC\u00DD\u00DE\u00DF\u00AA\u00AC\u00B1\u00B2\u00B3\u00B5\u00B9\u00BA\u00BC\u00BD\u00BE\u0080\u0081\u0082\u0083\u0084\u0085\u0086\u0087\u0088\u0089" +
75	        LATCHA + ' ' + LOCK + SHIFTD + SHIFTE + LATCHB,
76	    "\u00E0\u00E1\u00E2\u00E3\u00E4\u00E5\u00E6\u00E7\u00E8\u00E9\u00EA\u00EB\u00EC\u00ED\u00EE\u00EF\u00F0\u00F1\u00F2\u00F3\u00F4\u00F5\u00F6\u00F7\u00F8\u00F9\u00FA" +
77	        ECI + FS + GS + RS + NS +
78	        "\u00FB\u00FC\u00FD\u00FE\u00FF\u00A1\u00A8\u00AB\u00AF\u00B0\u00B4\u00B7\u00B8\u00BB\u00BF\u008A\u008B\u008C\u008D\u008E\u008F\u0090\u0091\u0092\u0093\u0094" +
79	        LATCHA + ' ' + SHIFTC + LOCK + SHIFTE + LATCHB,
80	    "\u0000\u0001\u0002\u0003\u0004\u0005\u0006\u0007\u0008\u0009\n\u000B\u000C\r\u000E\u000F\u0010\u0011\u0012\u0013\u0014\u0015\u0016\u0017\u0018\u0019\u001A" +
81	        ECI + PAD + PAD + '\u001B' + NS + FS + GS + RS +
82	        "\u001F\u009F\u00A0\u00A2\u00A3\u00A4\u00A5\u00A6\u00A7\u00A9\u00AD\u00AE\u00B6\u0095\u0096\u0097\u0098\u0099\u009A\u009B\u009C\u009D\u009E" +
83	        LATCHA + ' ' + SHIFTC + SHIFTD + LOCK + LATCHB,
84	  };
85	
86	  private DecodedBitStreamParser() {
87	  }
88	
89	  static DecoderResult decode(byte[] bytes, int mode) throws FormatException {
90	    StringBuilder result = new StringBuilder(144);
91	    switch (mode) {
92	      case 2:
93	      case 3:
94	        String postcode;
95	        if (mode == 2) {
96	          int pc = getPostCode2(bytes);
97	          int ps2Length = getPostCode2Length(bytes);
98	          if (ps2Length > 10) {
99	            throw FormatException.getFormatInstance();
100	          }
101	          NumberFormat df = new DecimalFormat("0000000000".substring(0, ps2Length),
102	              DecimalFormatSymbols.getInstance(Locale.ROOT));
103	          postcode = df.format(pc);
104	        } else {
105	          postcode = getPostCode3(bytes);
106	        }
107	        NumberFormat threeDigits = new DecimalFormat("000", DecimalFormatSymbols.getInstance(Locale.ROOT));
108	        String country = threeDigits.format(getCountry(bytes));
109	        String service = threeDigits.format(getServiceClass(bytes));
110	        result.append(getMessage(bytes, 10, 84));
111	        if (result.toString().startsWith("[)>" + RS + "01" + GS)) {
112	          if (result.length() < 9) {
113	            throw FormatException.getFormatInstance();
114	          }
115	          result.insert(9, postcode + GS + country + GS + service + GS);
116	        } else {
117	          result.insert(0, postcode + GS + country + GS + service + GS);
118	        }
119	        break;
120	      case 4:
121	        result.append(getMessage(bytes, 1, 93));
122	        break;
123	      case 5:
124	        result.append(getMessage(bytes, 1, 77));
125	        break;
126	    }
127	    return new DecoderResult(bytes, result.toString(), null, String.valueOf(mode));
128	  }
129	
130	  private static int getBit(int bit, byte[] bytes) {
131	    bit--;
132	    return (bytes[bit / 6] & (1 << (5 - (bit % 6)))) == 0 ? 0 : 1;
133	  }
134	
135	  private static int getInt(byte[] bytes, byte[] x) {
136	    int val = 0;
137	    for (int i = 0; i < x.length; i++) {
138	      val += getBit(x[i], bytes) << (x.length - i - 1);
139	    }
140	    return val;
141	  }
142	
143	  private static int getCountry(byte[] bytes) {
144	    return getInt(bytes, COUNTRY_BYTES);
145	  }
146	
147	  private static int getServiceClass(byte[] bytes) {
148	    return getInt(bytes, SERVICE_CLASS_BYTES);
149	  }
150	
151	  private static int getPostCode2Length(byte[] bytes) {
152	    return getInt(bytes, POSTCODE_2_LENGTH_BYTES);
153	  }
154	
155	  private static int getPostCode2(byte[] bytes) {
156	    return getInt(bytes, POSTCODE_2_BYTES);
157	  }
158	
159	  private static String getPostCode3(byte[] bytes) {
160	    StringBuilder sb = new StringBuilder(POSTCODE_3_BYTES.length);
161	    for (byte[] p3bytes : POSTCODE_3_BYTES) {
162	      sb.append(SETS[0].charAt(getInt(bytes, p3bytes)));
163	    }
164	    return sb.toString();
165	  }
166	
167	  private static String getMessage(byte[] bytes, int start, int len) throws FormatException {
168	    StringBuilder sb = new StringBuilder();
169	    int shift = -1;
170	    int set = 0;
171	    int lastset = 0;
172	    for (int i = start; i < start + len; i++) {
173	      char c = SETS[set].charAt(bytes[i]);
174	      switch (c) {
175	        case LATCHA:
176	          set = 0;
177	          shift = -1;
178	          break;
179	        case LATCHB:
180	          set = 1;
181	          shift = -1;
182	          break;
183	        case SHIFTA:
184	        case SHIFTB:
185	        case SHIFTC:
186	        case SHIFTD:
187	        case SHIFTE:
188	          lastset = set;
189	          set = c - SHIFTA;
190	          shift = 1;
191	          break;
192	        case TWOSHIFTA:
193	          lastset = set;
194	          set = 0;
195	          shift = 2;
196	          break;
197	        case THREESHIFTA:
198	          lastset = set;
199	          set = 0;
200	          shift = 3;
201	          break;
202	        case NS:
203	          if (i + 5 >= start + len) {
204	            throw FormatException.getFormatInstance();
205	          }
206	          int nsval = (bytes[++i] << 24) + (bytes[++i] << 18) + (bytes[++i] << 12) + (bytes[++i] << 6) + bytes[++i];
207	          sb.append(new DecimalFormat("000000000", DecimalFormatSymbols.getInstance(Locale.ROOT)).format(nsval));
208	          break;
209	        case LOCK:
210	          shift = -1;
211	          break;
212	        default:
213	          sb.append(c);
214	      }
215	      if (shift-- == 0) {
216	        set = lastset;
217	      }
218	    }
219	    while (sb.length() > 0 && sb.charAt(sb.length() - 1) == PAD) {
220	      sb.setLength(sb.length() - 1);
221	    }
222	    return sb.toString();
223	  }
224	
