17	package com.google.zxing.pdf417.detector;
18	
19	import com.google.zxing.BinaryBitmap;
20	import com.google.zxing.DecodeHintType;
21	import com.google.zxing.NotFoundException;
22	import com.google.zxing.ResultPoint;
23	import com.google.zxing.common.BitMatrix;
24	
25	import java.util.ArrayList;
26	import java.util.Arrays;
27	import java.util.List;
28	import java.util.Map;
29	
30	/**
31	 * <p>Encapsulates logic that can detect a PDF417 Code in an image, even if the
32	 * PDF417 Code is rotated or skewed, or partially obscured.</p>
33	 *
34	 * @author SITA Lab (kevin.osullivan@sita.aero)
35	 * @author dswitkin@google.com (Daniel Switkin)
36	 * @author Guenther Grau
37	 */
38	public final class Detector {
39	
40	  private static final int[] INDEXES_START_PATTERN = {0, 4, 1, 5};
41	  private static final int[] INDEXES_STOP_PATTERN = {6, 2, 7, 3};
42	  private static final float MAX_AVG_VARIANCE = 0.42f;
43	  private static final float MAX_INDIVIDUAL_VARIANCE = 0.8f;
44	  private static final float MAX_STOP_PATTERN_HEIGHT_VARIANCE = 0.5f;
45	
46	  // B S B S B S B S Bar/Space pattern
47	  // 11111111 0 1 0 1 0 1 000
48	  private static final int[] START_PATTERN = {8, 1, 1, 1, 1, 1, 1, 3};
49	  // 1111111 0 1 000 1 0 1 00 1
50	  private static final int[] STOP_PATTERN = {7, 1, 1, 3, 1, 1, 1, 2, 1};
51	  private static final int MAX_PIXEL_DRIFT = 3;
52	  private static final int MAX_PATTERN_DRIFT = 5;
53	  // if we set the value too low, then we don't detect the correct height of the bar if the start patterns are damaged.
54	  // if we set the value too high, then we might detect the start pattern from a neighbor barcode.
55	  private static final int SKIPPED_ROW_COUNT_MAX = 25;
56	  // A PDF471 barcode should have at least 3 rows, with each row being >= 3 times the module width.
57	  // Therefore it should be at least 9 pixels tall. To be conservative, we use about half the size to
58	  // ensure we don't miss it.
59	  private static final int ROW_STEP = 5;
60	  private static final int BARCODE_MIN_HEIGHT = 10;
61	  private static final int[] ROTATIONS = {0, 180, 270, 90};
62	
63	  private Detector() {
64	  }
65	
66	  /**
67	   * <p>Detects a PDF417 Code in an image. Checks 0, 90, 180, and 270 degree rotations.</p>
68	   *
69	   * @param image barcode image to decode
70	   * @param hints optional hints to detector
71	   * @param multiple if true, then the image is searched for multiple codes. If false, then at most one code will
72	   * be found and returned
73	   * @return {@link PDF417DetectorResult} encapsulating results of detecting a PDF417 code
74	   * @throws NotFoundException if no PDF417 Code can be found
75	   */
76	  public static PDF417DetectorResult detect(BinaryBitmap image, Map<DecodeHintType,?> hints, boolean multiple)
77	      throws NotFoundException {
78	    // TODO detection improvement, tryHarder could try several different luminance thresholds/blackpoints or even
79	    // different binarizers
80	    //boolean tryHarder = hints != null && hints.containsKey(DecodeHintType.TRY_HARDER);
81	
82	    BitMatrix originalMatrix = image.getBlackMatrix();
83	    for (int rotation : ROTATIONS) {
84	      BitMatrix bitMatrix = applyRotation(originalMatrix, rotation);
85	      List<ResultPoint[]> barcodeCoordinates = detect(multiple, bitMatrix);
86	      if (!barcodeCoordinates.isEmpty()) {
87	        return new PDF417DetectorResult(bitMatrix, barcodeCoordinates, rotation);
88	      }
89	    }
90	    return new PDF417DetectorResult(originalMatrix, new ArrayList<>(), 0);
91	  }
92	
93	  /**
94	   * Applies a rotation to the supplied BitMatrix.
95	   * @param matrix bit matrix to apply rotation to
96	   * @param rotation the degrees of rotation to apply
97	   * @return BitMatrix with applied rotation
98	   */
99	  private static BitMatrix applyRotation(BitMatrix matrix, int rotation) {
100	    if (rotation % 360 == 0) {
101	      return matrix;
102	    }
103	
104	    BitMatrix newMatrix = matrix.clone();
105	    newMatrix.rotate(rotation);
106	    return newMatrix;
107	  }
108	
109	  /**
110	   * Detects PDF417 codes in an image. Only checks 0 degree rotation
111	   * @param multiple if true, then the image is searched for multiple codes. If false, then at most one code will
112	   * be found and returned
113	   * @param bitMatrix bit matrix to detect barcodes in
114	   * @return List of ResultPoint arrays containing the coordinates of found barcodes
115	   */
116	  private static List<ResultPoint[]> detect(boolean multiple, BitMatrix bitMatrix) {
117	    List<ResultPoint[]> barcodeCoordinates = new ArrayList<>();
118	    int row = 0;
119	    int column = 0;
120	    boolean foundBarcodeInRow = false;
121	    while (row < bitMatrix.getHeight()) {
122	      ResultPoint[] vertices = findVertices(bitMatrix, row, column);
123	
124	      if (vertices[0] == null && vertices[3] == null) {
125	        if (!foundBarcodeInRow) {
126	          // we didn't find any barcode so that's the end of searching
127	          break;
128	        }
129	        // we didn't find a barcode starting at the given column and row. Try again from the first column and slightly
130	        // below the lowest barcode we found so far.
131	        foundBarcodeInRow = false;
132	        column = 0;
133	        for (ResultPoint[] barcodeCoordinate : barcodeCoordinates) {
134	          if (barcodeCoordinate[1] != null) {
135	            row = (int) Math.max(row, barcodeCoordinate[1].getY());
136	          }
137	          if (barcodeCoordinate[3] != null) {
138	            row = Math.max(row, (int) barcodeCoordinate[3].getY());
139	          }
140	        }
141	        row += ROW_STEP;
142	        continue;
143	      }
144	      foundBarcodeInRow = true;
145	      barcodeCoordinates.add(vertices);
146	      if (!multiple) {
147	        break;
148	      }
149	      // if we didn't find a right row indicator column, then continue the search for the next barcode after the
150	      // start pattern of the barcode just found.
151	      if (vertices[2] != null) {
152	        column = (int) vertices[2].getX();
153	        row = (int) vertices[2].getY();
154	      } else {
155	        column = (int) vertices[4].getX();
156	        row = (int) vertices[4].getY();
157	      }
158	    }
159	    return barcodeCoordinates;
160	  }
161	
162	  /**
163	   * Locate the vertices and the codewords area of a black blob using the Start
164	   * and Stop patterns as locators.
165	   *
166	   * @param matrix the scanned barcode image.
167	   * @return an array containing the vertices:
168	   *           vertices[0] x, y top left barcode
169	   *           vertices[1] x, y bottom left barcode
170	   *           vertices[2] x, y top right barcode
171	   *           vertices[3] x, y bottom right barcode
172	   *           vertices[4] x, y top left codeword area
173	   *           vertices[5] x, y bottom left codeword area
174	   *           vertices[6] x, y top right codeword area
175	   *           vertices[7] x, y bottom right codeword area
176	   */
177	  private static ResultPoint[] findVertices(BitMatrix matrix, int startRow, int startColumn) {
178	    int height = matrix.getHeight();
179	    int width = matrix.getWidth();
180	
181	    ResultPoint[] result = new ResultPoint[8];
182	    int minHeight = BARCODE_MIN_HEIGHT;
183	    copyToResult(result, findRowsWithPattern(matrix, height, width, startRow, startColumn, minHeight, START_PATTERN),
184	        INDEXES_START_PATTERN);
185	
186	    if (result[4] != null) {
187	      startColumn = (int) result[4].getX();
188	      startRow = (int) result[4].getY();
189	      if (result[5] != null) {
190	        int endRow = (int) result[5].getY();
191	        int startPatternHeight = endRow - startRow;
192	        minHeight = (int) Math.max(startPatternHeight * MAX_STOP_PATTERN_HEIGHT_VARIANCE, BARCODE_MIN_HEIGHT);
193	      }
194	    }
195	    copyToResult(result, findRowsWithPattern(matrix, height, width, startRow, startColumn, minHeight, STOP_PATTERN),
196	        INDEXES_STOP_PATTERN);
197	    return result;
198	  }
199	
200	  private static void copyToResult(ResultPoint[] result, ResultPoint[] tmpResult, int[] destinationIndexes) {
201	    for (int i = 0; i < destinationIndexes.length; i++) {
202	      result[destinationIndexes[i]] = tmpResult[i];
203	    }
204	  }
205	
206	  private static ResultPoint[] findRowsWithPattern(BitMatrix matrix,
207	                                                   int height,
208	                                                   int width,
209	                                                   int startRow,
210	                                                   int startColumn,
211	                                                   int minHeight,
212	                                                   int[] pattern) {
213	    ResultPoint[] result = new ResultPoint[4];
214	    boolean found = false;
215	    int minStartRow = startRow;
216	    int[] counters = new int[pattern.length];
217	    for (; startRow < height; startRow += ROW_STEP) {
218	      int[] loc = findGuardPattern(matrix, startColumn, startRow, width, pattern, counters);
219	      if (loc != null) {
220	        while (startRow > minStartRow + 1) {
221	          int[] previousRowLoc = findGuardPattern(matrix, startColumn, --startRow, width, pattern, counters);
222	          if (previousRowLoc != null) {
223	            loc = previousRowLoc;
224	          } else {
225	            startRow++;
226	            break;
227	          }
228	        }
229	        result[0] = new ResultPoint(loc[0], startRow);
230	        result[1] = new ResultPoint(loc[1], startRow);
231	        found = true;
232	        break;
233	      }
234	    }
235	    int stopRow = startRow + 1;
236	    // Last row of the current symbol that contains pattern
237	    if (found) {
238	      int skippedRowCount = 0;
239	      int[] previousRowLoc = {(int) result[0].getX(), (int) result[1].getX()};
240	      for (; stopRow < height; stopRow++) {
241	        int[] loc = findGuardPattern(matrix, previousRowLoc[0], stopRow, width, pattern, counters);
242	        // a found pattern is only considered to belong to the same barcode if the start and end positions
243	        // don't differ too much. Pattern drift should be not bigger than two for consecutive rows. With
244	        // a higher number of skipped rows drift could be larger. To keep it simple for now, we allow a slightly
245	        // larger drift and don't check for skipped rows.
246	        if (loc != null &&
247	            Math.abs(previousRowLoc[0] - loc[0]) < MAX_PATTERN_DRIFT &&
248	            Math.abs(previousRowLoc[1] - loc[1]) < MAX_PATTERN_DRIFT) {
249	          previousRowLoc = loc;
250	          skippedRowCount = 0;
251	        } else {
252	          if (skippedRowCount > SKIPPED_ROW_COUNT_MAX) {
253	            break;
254	          } else {
255	            skippedRowCount++;
256	          }
257	        }
258	      }
259	      stopRow -= skippedRowCount + 1;
260	      result[2] = new ResultPoint(previousRowLoc[0], stopRow);
261	      result[3] = new ResultPoint(previousRowLoc[1], stopRow);
262	    }
263	    if (stopRow - startRow < minHeight) {
264	      Arrays.fill(result, null);
265	    }
266	    return result;
267	  }
268	
269	  /**
270	   * @param matrix row of black/white values to search
271	   * @param column x position to start search
272	   * @param row y position to start search
273	   * @param width the number of pixels to search on this row
274	   * @param pattern pattern of counts of number of black and white pixels that are
275	   *                 being searched for as a pattern
276	   * @param counters array of counters, as long as pattern, to re-use
277	   * @return start/end horizontal offset of guard pattern, as an array of two ints.
278	   */
279	  private static int[] findGuardPattern(BitMatrix matrix,
280	                                        int column,
281	                                        int row,
282	                                        int width,
283	                                        int[] pattern,
284	                                        int[] counters) {
285	    Arrays.fill(counters, 0, counters.length, 0);
286	    int patternStart = column;
287	    int pixelDrift = 0;
288	
289	    // if there are black pixels left of the current pixel shift to the left, but only for MAX_PIXEL_DRIFT pixels
290	    while (matrix.get(patternStart, row) && patternStart > 0 && pixelDrift++ < MAX_PIXEL_DRIFT) {
291	      patternStart--;
292	    }
293	    int x = patternStart;
294	    int counterPosition = 0;
295	    int patternLength = pattern.length;
296	    for (boolean isWhite = false; x < width; x++) {
297	      boolean pixel = matrix.get(x, row);
298	      if (pixel != isWhite) {
299	        counters[counterPosition]++;
300	      } else {
301	        if (counterPosition == patternLength - 1) {
302	          if (patternMatchVariance(counters, pattern) < MAX_AVG_VARIANCE) {
303	            return new int[] {patternStart, x};
304	          }
305	          patternStart += counters[0] + counters[1];
306	          System.arraycopy(counters, 2, counters, 0, counterPosition - 1);
307	          counters[counterPosition - 1] = 0;
308	          counters[counterPosition] = 0;
309	          counterPosition--;
310	        } else {
311	          counterPosition++;
312	        }
313	        counters[counterPosition] = 1;
314	        isWhite = !isWhite;
315	      }
316	    }
317	    if (counterPosition == patternLength - 1 &&
318	        patternMatchVariance(counters, pattern) < MAX_AVG_VARIANCE) {
319	      return new int[] {patternStart, x - 1};
320	    }
321	    return null;
322	  }
323	
324	  /**
325	   * Determines how closely a set of observed counts of runs of black/white
326	   * values matches a given target pattern. This is reported as the ratio of
327	   * the total variance from the expected pattern proportions across all
328	   * pattern elements, to the length of the pattern.
329	   *
330	   * @param counters observed counters
331	   * @param pattern expected pattern
332	   * @return ratio of total variance between counters and pattern compared to total pattern size
333	   */
334	  private static float patternMatchVariance(int[] counters, int[] pattern) {
335	    int numCounters = counters.length;
336	    int total = 0;
337	    int patternLength = 0;
338	    for (int i = 0; i < numCounters; i++) {
339	      total += counters[i];
340	      patternLength += pattern[i];
341	    }
342	    if (total < patternLength) {
343	      // If we don't even have one pixel per unit of bar width, assume this
344	      // is too small to reliably match, so fail:
345	      return Float.POSITIVE_INFINITY;
346	    }
347	    // We're going to fake floating-point math in integers. We just need to use more bits.
348	    // Scale up patternLength so that intermediate values below like scaledCounter will have
349	    // more "significant digits".
350	    float unitBarWidth = (float) total / patternLength;
351	    float maxIndividualVariance = MAX_INDIVIDUAL_VARIANCE * unitBarWidth;
352	
353	    float totalVariance = 0.0f;
354	    for (int x = 0; x < numCounters; x++) {
355	      int counter = counters[x];
356	      float scaledPattern = pattern[x] * unitBarWidth;
357	      float variance = counter > scaledPattern ? counter - scaledPattern : scaledPattern - counter;
358	      if (variance > maxIndividualVariance) {
359	        return Float.POSITIVE_INFINITY;
360	      }
361	      totalVariance += variance;
362	    }
363	    return totalVariance / total;
364	  }
365	}
